export const BRIGHT_ANCHOR_URI = "data:image/png;base64,";

export function AnchorLogo({
  size,
  className = "h-5 w-5",
}: {
  size?: number;
  className?: string;
  gradient?: boolean;
}) {
  return (
    <div
      className={`relative inline-flex shrink-0 items-center justify-center select-none ${className}`}
      style={size ? { width: size, height: size } : undefined}
    >
      <img
        src={BRIGHT_ANCHOR_URI}
        alt="Portside Anchor"
        className="relative z-10 h-full w-full object-contain drop-shadow-[0_2px_8px_rgba(56,189,248,0.45)]"
        draggable={false}
      />
    </div>
  );
}

export function AnchorIconBox({ size = "md" }: { size?: "sm" | "md" | "lg" }) {
  const boxClasses = {
    sm: "h-7 w-7 rounded-lg",
    md: "h-9 w-9 rounded-xl",
    lg: "h-11 w-11 rounded-xl",
  }[size];

  const iconClasses = {
    sm: "h-5 w-5",
    md: "h-6.5 w-6.5",
    lg: "h-8.5 w-8.5",
  }[size];

  return (
    <span
      className={`inline-flex shrink-0 items-center justify-center bg-[#070e1c] border border-sky-400/40 shadow-xs shadow-sky-500/25 ${boxClasses}`}
    >
      <AnchorLogo className={iconClasses} />
    </span>
  );
}
